def compile_lineage(inv: Invocation) -> dict[str, Any]:
    from management_portal.society_service import lineage_program

    lineage = domain().get_lineage_definition_for_analysis(inv.argument("lineage_id"), inv.caller)
    plan = lineage_program.compile_program(lineage.get("program"), lineage.get("nodes") or [])
    diagnostics = [
        {"code": code, "item_id": effect_id, "line": line, "message": message}
        for effect_id, effect in plan["effects"].items()
        for code, message, line in lineage_program.effect_script_analysis(effect).diagnostics
    ]
    if diagnostics:
        raise invalid("Effect 脚本编译失败", diagnostics=diagnostics)
    return {"program": plan}

